// Repository: che giấu cách lưu trữ. Đổi CSDL không làm đổi tầng nghiệp vụ.
function makeUserRepo() {
  const rows = [{ id: 1, name: "An", active: true }, { id: 2, name: "Bình", active: false }, { id: 3, name: "Chi", active: true }];
  return {
    findById: async (id) => rows.find((r) => r.id === id) ?? null,
    listActive: async () => rows.filter((r) => r.active),
  };
}

// Query builder an toàn: trả {text, values}; giá trị KHÔNG bao giờ nằm trong text
function selectWhere(table, conds) {
  const keys = Object.keys(conds);
  const where = keys.map((k, i) => k + " = $" + (i + 1)).join(" AND ");
  return { text: "SELECT * FROM " + table + (where ? " WHERE " + where : ""), values: keys.map((k) => conds[k]) };
}

(async () => {
  const repo = makeUserRepo();
  console.log((await repo.listActive()).map((u) => u.name).join(","));
  console.log(JSON.stringify(selectWhere("users", { name: "An", active: true })));
})();

