const accounts = { a: 100, b: 0 };
function transfer(acc, from, to, amount) {
  if (acc[from] < amount) throw new Error("insufficient funds");
  acc[from] -= amount;
  acc[to] += amount;
}
transfer(accounts, "a", "b", 30);
const s1 = accounts.a + "," + accounts.b;
try { transfer(accounts, "a", "b", 500); } catch (e) {}
console.log(s1 + "|" + accounts.a + "," + accounts.b);

