const rows = [1, 2, 3, 4, 5].map((id) => ({ id }));
function page(rows, afterId, limit) {
  const rest = rows.filter((r) => r.id > afterId);
  const items = rest.slice(0, limit);
  const nextCursor = rest.length > limit ? items[items.length - 1].id : null;
  return { items: items.map((r) => r.id), nextCursor };
}
console.log(JSON.stringify(page(rows, 0, 2)) + "|" + JSON.stringify(page(rows, 4, 2)));
